def _allow_redirect(redirect_url: str | None) -> bool:
    """Return True if redirect_url is one of our own post-login pages."""

    if not redirect_url:
        return False

    # Reject backslashes and control characters: browsers may normalize
    # them in ways that turn a "relative" URL into a protocol-relative one.
    if "\\" in redirect_url or any(ord(c) < 32 for c in redirect_url):
        return False

    parsed = urlparse(redirect_url)
    if parsed.scheme or parsed.netloc:
        return False

    if not parsed.path.startswith("/") or parsed.path.startswith("//"):
        return False

    try:
        match = resolve(parsed.path)
    except Resolver404:
        return False

    return match.url_name in POST_LOGIN_ROUTES

